/// <summary>
/// Handler class for importing files from an SFTP server
/// </summary>
class OMGInboundTransport_SFTP extends OMGInboundTransport
{
    OMGSftpReader               sftpReader;
    OMGInboundDataContract_SFTP dataContract;
    int                         messageCounter;
    int64                       messageSize;

}

Method.Source:
/// <summary>
/// Returns the number of messages fetched
/// </summary>
/// <returns>Number of messages</returns>
protected int64 messageCount()
{
    return messageCounter;
}

/// <summary>
/// Returns the total size of the messages fetched
/// </summary>
/// <returns>Size in bytes</returns>
protected int64 messageSize()
{
    return messageSize;
}

/// <summary>
/// Imports the files
/// </summary>
/// <param name = "_dataContract">Data contract holding the messageTypeId</param>
public void doTransport(OMGInboundTransportContract _dataContract)
{
    OMGMessageTypeTable                     messageTypeTable = OMGMessageTypeTable::find(_dataContract.parmMessageTypeId());
    Map                                     fileMap;
    ;

    dataContract = FormJsonSerializer::deserializeObject(this.dataContractClass(), messageTypeTable.InboundSerializedParameterContract) as OMGInboundDataContract_SFTP;

    if (dataContract && dataContract.parmHostName() && dataContract.parmUserName() && dataContract.parmKeyVaultCertificateRef())
    {
        sftpReader = OMGSftpReader::newFromContract(dataContract);

        fileMap = sftpReader.buildFileHandleMap();
        this.processFileMap(fileMap, dataContract.parmCodePage(), messageTypeTable.MessageTypeId);

        sftpReader.close();
    }
    else
    {
        Error(strFmt("@OMG:FaultyMessageTypeParameters", messageTypeTable.MessageTypeId));
    }

    info(strFmt("@OMG:MessagesFetched", messageTypeTable.MessageTypeId, messageCounter));
}

/// <summary>
/// Imports the files in the map
/// </summary>
/// <param name = "_fileMap">The map of files</param>
/// <param name = "_codePage">The codepage in the files</param>
/// <param name = "_messageTypeId">The message type</param>
public void processFileMap(Map              _fileMap,
                           DMFCodePage      _codePage,
                           OMGMessageTypeId _messageTypeId)
{
    MapEnumerator   mapEnumerator = _fileMap.getEnumerator();
    OMGMessage      oMGMessage;
    container       valueContainer; //Full path, file name, modified date/time
    ;

    while (mapEnumerator.moveNext())
    {
        valueContainer = mapEnumerator.currentValue();

        oMGMessage = sftpReader.readSingleFile(conPeek(valueContainer, 1), dataContract.parmBase64Encode(), _codePage);

        this.generateInboundMessage(oMGMessage, conPeek(valueContainer, 1), conPeek(valueContainer, 2), _messageTypeId, conPeek(valueContainer, 3));
    }
}

/// <summary>
/// Generates a record in the inbound message table based on the file
/// </summary>
/// <param name = "_message">The message content</param>
/// <param name = "_fullFileName">The full path of the file</param>
/// <param name = "_fileName">The name of the file</param>
/// <param name = "_messageTypeId">The message type</param>
/// <param name = "_modifiedValue">The modified date/time</param>
public void generateInboundMessage(OMGMessage               _message,
                                   Filename                 _fullFileName,
                                   Filename                 _fileName,
                                   OMGMessageTypeId         _messageTypeId,
                                   utcdatetime              _modifiedValue)
{
    OMGInboundMessageTable  inboundMessageTable;

    try
    {
        ttsbegin;

        inboundMessageTable = OMGInboundMessageTable::createInboundMessage(_fileName,
                                                                           _messageTypeId,
                                                                           _message,
                                                                           dataContract.parmBase64Encode(),
                                                                           OMGMessageTypeTable::find(_messageTypeId).Company,
                                                                           newGuid(),
                                                                           _modifiedValue);

        // Handles the post import action (Archive/Delete/NoAction)
        sftpReader.postImportAction(dataContract, _fullFileName, _fileName);

        ttscommit;

        this.onInboundMessageInserted(inboundMessageTable);

        messageCounter++;
        messageSize += strLen(_message);
    }

    catch (Exception::Error)
    {
        throw Error("@ElectronicReporting:ImportCancelled");
    }
}

/// <summary>
/// Description of class
/// </summary>
/// <returns>The description</returns>
public static Description description()
{
    return "@OMG:ImportFilesFromSftp";
}
